export function searchCities(query, limit = 8) {
  const text = String(query || "").trim().toLowerCase();
  if (!text) return [];
  const found = [];
  for (const city of cities) {
    if (city[0].toLowerCase().includes(text) || city[1].includes(text) || city[2].includes(text)) {
      found.push(city);
      if (found.length >= limit) break;
    }
  }
  return found;
}

export function nearestCity(lat, lng) {
  const rad = Math.PI / 180;
  const cos = Math.cos(lat * rad);
  let best = cities[0];
  let bestScore = Infinity;
  for (const city of cities) {
    const dLat = (city[3] - lat) * rad;
    const dLng = (city[4] - lng) * rad * cos;
    const score = dLat * dLat + dLng * dLng;
    if (score < bestScore) {
      bestScore = score;
      best = city;
    }
  }
  return best;
}

export function cityName(city) {
  return city[0];
}

export function cityLine(city) {
  return `${city[0]} · ${city[2]}`;
}
